</head>

<body style="font-family: 'Titillium Web', sans-serif;">
    <table style="width:800px;border-radius:5px;margin:50px auto;" cellpadding="0px" cellspacing="0px">
        <thead>
            <tr style="height:100px; border:none;border:1px solid #2e2e2e;">
                <td style="border:none;height:100px;"><img src="{{LOGO}}" width="450px" style="margin-left:20px;"></td>
                <td style="border:none; padding:10px;" align="right">
                    <p style="margin:0em;font-size:18px;font-weight: 500;color:#2d2f93;;text-align:right;font-family: 'Titillium Web', sans-serif;">
                        {{BADDRESS}} <br>
                        {{BCITY}}, {{BSTATE}} {{BCODE}} </p>
                    <p style="font-size:20px;font-weight:400;color:#2d2f93;text-align:right;margin-right:20px;margin:0px; margin-top:15px;font-family: 'Titillium Web', sans-serif;">
                        <strong style="color:#000000;"> Call Us Now</strong> {{BPHONE}}
                    </p>
                </td>
            </tr>
            <tr style="height:10px; border:none;">
                <td style="border:none;" colspan="2">&nbsp;</td>
            </tr>
        </thead>
        <tbody>
            <tr style="margin-top:15px;border-bottom:0px;">
                <td style="text-align:left;padding-top: 0;border-top: 1px solid #000;border-left: 1px solid #000;">
                    <h1
                        style="padding:0px 15px;color: #2d2f93;text-align: left;margin: 0;font-size: 25px;font-weight:bold;margin-bottom:0px;font-family: 'Titillium Web', sans-serif;">
                        {{YEAR}} {{MAKE}} {{MODEL}} </h1>
                    
                </td>
				<td style="text-align:left;padding-top: 0;border-top: 1px solid #000;border-right: 1px solid #000; padding:0px 15px;">
                    <h3 style="color: #2d2f93;text-align: right;margin: 0;font-size: 20px;font-weight:bold;margin-bottom:0px;font-family: 'Titillium Web', sans-serif;">
                        {{ODOMETER}} {{KM_MILES}} </h3>
                    
                </td>
            </tr>
            <tr style="height:70px;">
                <td colspan="2" style="border:1px solid #2e2e2e;border-top:0px;">
                    <table width="100%" style="text-align:center;">
                        <tbody>
                            <tr>
                                <td style=" float:none;"><strong style="font-size: 14px;">Stock# </strong> <br>
                                    <span style="display:block;font-size:18px;font-weight: 600;color: #999; min-height:30px;">
                                        {{STOCK}}</span>
                                </td>
                                <td style="float:none;"><strong style="font-size: 14px;">Transmission </strong> <br>
                                    <span style="display:block;font-size:18px;font-weight: 600;color: #999;min-height:30px;">
                                        {{TRANSMISSION}} </span>
                                </td>
                                <td style="float:none;"><strong style="font-size: 14px;">Door </strong> <br>
                                    <span
                                        style="display:block;font-size:18px;font-weight: 600;color: #999;min-height:30px;">{{DOOR}}</span>
                                </td>
                                <td style="float:none;"><strong style="font-size: 14px;">Exterior </strong> <br>
                                    <span style="display:block;font-size:18px;font-weight: 600;color: #999;min-height:30px;">
                                        {{EXTERIOR_COLOR}} </span>
                                </td>
                                <td style="float:none;"><strong style="font-size: 14px;">Interior </strong> <br>
                                    <span style="display:block;font-size:18px;font-weight: 600;color: #999;min-height:30px;">
                                        {{INTERIOR_COLOR}} </span>
                                </td>
                                <td style="float:none;"><strong style="font-size: 14px;">Engine </strong> <br>
                                    <span style="display:block;font-size:18px;font-weight: 600;color: #999;min-height:30px;">{{ENGINE}}
                                    </span>
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </td>
            </tr>
            <tr style="height: 10px;border:none;">
                <td style="border:none;" colspan="2">&nbsp;</td>
            </tr>
            <tr height="250px">
                <td style="border:1px solid #2e2e2e;padding-bottom:4px;width:40%;" height="200px">
                    <table width="100%" style="text-align:left;">
                        <tbody>
                            <tr>
                                <td style=" float:none;" align="center" rowspan="4" valign="middle">
                                    <img src="{{IMAGE}}" width="350px" height="350px">
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </td>
                <td style="border:1px solid #2e2e2e;padding-bottom:4px;width:60%;padding:5px;" valign="middle" align="center">
                    <table width="100%" style="text-align:left;" align="center;">
                        <tbody>
                            <tr>
                                <td style=" float:left;width:100%;">
                                    
                                </td>
                            </tr>
                            <tr>
                                <td style="float:left;" valign="middle" align="center;">
								 <p style="padding-top: 0px;font-size: 18px;padding-bottom:8px;"> SCAN ME!</p>
                                    <p style="margin:0px;color: #000;font-size: 13px;font-weight: 300; line-height:27px;"> {{QR}} </p>
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </td>
            </tr>
            <tr style="height: 10px;border:none;">
                <td style="border:none;" colspan="2">&nbsp;</td>
            </tr>
			
			 <tr>
                <td style="border:1px solid #2e2e2e;padding-bottom:4px;" colspan="2">
                    <table width="100%">
                        <tbody>
                            <tr>
                                <td style="float:none;padding: 0px 0px;" colspan="10" valign="middle">
								<h6 style="color: #000;letter-spacing: 1px;font-weight:bold;margin:0px; position: relative;padding-bottom: 10px;font-size: 16px;text-transform: uppercase;"> Vehicle Description </h6>
                                    <p style="font-size: 18px;line-height: 22px;"> {{DESCRIPTION_1000}} </p>
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </td>
            </tr>
			
            <tr style="height:10px;">
                <td style="border:1px solid #2e2e2e;padding-bottom:4px;width:30%;height:10px;">
                    <table width="100%" style="text-align:center;">
                        <tbody>
                            <tr>
                                <td style=" float:none;" rowspan="3" valign="middle">
                                    <img src="data:image/png;base64,"
                                        width="50px" style="margin-left:20px;"> <strong style="font-size:20px;">Fuel Economy</strong>
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </td>
                <td style="border:1px solid #2e2e2e;padding-bottom:4px;width:30%;padding:10px;">
                    <table width="100%" style="text-align:center;">
                        <tbody>
                            <tr>
                                <td>
                                    <h4
                                        style="font-size:20px; font-weight:bold; color:#c7081b; display:block; margin:0px;">
                                        {{FUEL_CITY}} L/100 <strong style="width:50px; font-size:22px;;color:#c7081b;"> City
                                        </strong>
                                    </h4>
                                    <h4 style="font-size:20px; font-weight:bold; color:#c7081b;margin:0px;">
                                        {{FUEL_HWY}} L/100 <strong style="width:50px; font-size:22px;"> HWY </strong>
                                    </h4>
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </td>
            </tr>
            <tr style="height:10px; border:none;">
                <td style="border:none;" colspan="2">&nbsp;</td>
            </tr>
            <tr>
                <td style="border:1px solid #2e2e2e;padding-bottom:4px;padding: 0;" colspan="2">
                    <table width="100%" style="text-align:center;">
                        <tbody>
                            <tr>
                                <td style=" float:none;padding:00px 0px;" colspan="10" valign="middle">
                                    <h2 style="font-size:40px;font-weight:bold;color:#999;margin: 0px;">Your Price:
                                        <span style="font-size: 30px;font-weight:bold;color:#c7081b;">${{PRICE}} <br/><strong style="font-size: 15px;font-weight: 600;color: #000;">Plus documentation fee and and applicable taxes </strong>
                                        </span>
                                        <!-- <strike style="font-size:20px; font-weight:bold; color:#000;"> $21,000.00 </strike> -->
                                    </h2>
                                   
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </td>
            </tr>
            <tr style="height:10px; border:none;">
                <td style="border:none;" colspan="2">&nbsp;</td>
            </tr>
           
        </tbody>
    </table>


</body>

</html>